import {
	KEATING_UI_PROTOCOL,
	KEATING_UI_VERSION,
	type JsonObject,
	type UiDocument,
	type UiDocumentKind,
} from "./types";

const TAG_KIND: Record<string, UiDocumentKind> = {
	quiz: "quiz",
	question: "question",
	goal: "goal",
	deck: "deck",
	image: "image",
	animation: "scene",
	scene: "scene",
};

export interface LegacyDocumentOptions {
	id: string;
	revision?: number;
	title?: string;
}

export function decodeLegacyTagPayload(encoded: string): unknown {
	let value: unknown = encoded.trim();
	for (let pass = 0; pass < 2 && typeof value === "string"; pass++) {
		try {
			value = JSON.parse(value);
		} catch {
			break;
		}
	}
	return value;
}

function object(value: unknown): Record<string, unknown> {
	return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

function strings(value: unknown): string[] | undefined {
	return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : undefined;
}

function normalizePayload(kind: UiDocumentKind, raw: unknown): JsonObject {
	const source = object(raw);
	switch (kind) {
		case "quiz":
			return { ...source, topic: String(source.topic ?? "Quiz"), questions: Array.isArray(source.questions) ? source.questions : [] } as JsonObject;
		case "question": {
			const rawFields = Array.isArray(source.questions) ? source.questions : source.fields;
			const fields = Array.isArray(rawFields)
				? rawFields.map((field, index) => {
					const item = object(field);
					return { ...item, id: String(item.id ?? `question-${index + 1}`), prompt: String(item.prompt ?? item.question ?? "Question"), type: String(item.type ?? "text") };
				})
				: [{ id: "question-1", prompt: String(source.question ?? "Question"), type: String(source.type ?? "text"), choices: strings(source.choices) }];
			return { intro: typeof source.intro === "string" ? source.intro : undefined, topic: typeof source.topic === "string" ? source.topic : undefined, fields } as JsonObject;
		}
		case "goal":
			return { ...source, goalId: String(source.goalId ?? source.id ?? "legacy-goal"), title: String(source.title ?? "Goal"), status: String(source.status ?? "active"), steps: Array.isArray(source.steps) ? source.steps : [] } as JsonObject;
		case "deck":
			return { ...source, deckId: String(source.deckId ?? source.id ?? "legacy-deck"), topic: String(source.topic ?? "Flashcards"), title: String(source.title ?? "Flashcards"), cards: Array.isArray(source.cards) ? source.cards : [] } as JsonObject;
		case "image":
			return { ...source, title: String(source.title ?? "Generated image"), alt: String(source.alt ?? source.title ?? "Generated image") } as JsonObject;
		case "scene":
			return { ...source } as JsonObject;
		default:
			return { format: "json", data: raw as never };
	}
}

export function legacyPayloadToUiDocument(tagKind: string, payload: unknown, options: LegacyDocumentOptions): UiDocument {
	const kind = TAG_KIND[tagKind] ?? "generic";
	const normalized = kind === "generic"
		? { format: "json", data: payload as never, originalKind: tagKind }
		: normalizePayload(kind, payload);
	return {
		protocol: KEATING_UI_PROTOCOL,
		version: KEATING_UI_VERSION,
		id: options.id,
		revision: options.revision ?? 0,
		kind,
		...(options.title ? { title: options.title } : {}),
		payload: normalized,
	} as UiDocument;
}

/** Parses one legacy self-closing Keating tag emitted by browser tools. */
export function legacyTagToUiDocument(tag: string, options: LegacyDocumentOptions): UiDocument | undefined {
	const match = tag.match(/^<keating-([\w-]+)\s+(?:json|markdown)=((?:"(?:\\.|[^"\\])*")|(?:'[^']*'))\s*\/>$/s);
	if (!match) return undefined;
	const [, tagKind, encoded] = match;
	if (!tagKind || !encoded) return undefined;
	const decoded = decodeLegacyTagPayload(encoded[0] === "'" ? JSON.stringify(encoded.slice(1, -1)) : encoded);
	return legacyPayloadToUiDocument(tagKind, decoded, options);
}

import {
	KEATING_UI_PROTOCOL,
	KEATING_UI_VERSION,
	type JsonObject,
	type JsonValue,
	type UiActionRequest,
	type UiActionResult,
	type UiDocument,
	type UiDocumentKind,
} from "./types";

export interface ValidationResult<T> {
	ok: boolean;
	value?: T;
	errors: string[];
}

const DOCUMENT_KINDS = new Set<UiDocumentKind>([
	"quiz", "question", "goal", "deck", "image", "scene", "artifact", "generic",
]);

function record(value: unknown): value is Record<string, unknown> {
	return !!value && typeof value === "object" && !Array.isArray(value);
}

function nonEmptyString(value: unknown): value is string {
	return typeof value === "string" && value.trim().length > 0;
}

function revision(value: unknown): value is number {
	return Number.isSafeInteger(value) && (value as number) >= 0;
}

export function isJsonValue(value: unknown, seen = new Set<object>()): value is JsonValue {
	if (value === null || typeof value === "string" || typeof value === "boolean") return true;
	if (typeof value === "number") return Number.isFinite(value);
	if (typeof value !== "object") return false;
	if (seen.has(value as object)) return false;
	seen.add(value as object);
	const valid = Array.isArray(value)
		? value.every((entry) => isJsonValue(entry, seen))
		: Object.entries(value as Record<string, unknown>).every(
			([key, entry]) => key !== "__proto__" && isJsonValue(entry, seen),
		);
	seen.delete(value as object);
	return valid;
}

function validateActions(value: unknown, errors: string[]): void {
	if (value === undefined) return;
	if (!Array.isArray(value)) {
		errors.push("actions must be an array");
		return;
	}
	const ids = new Set<string>();
	for (const [index, action] of value.entries()) {
		if (!record(action)) {
			errors.push(`actions[${index}] must be an object`);
			continue;
		}
		if (!nonEmptyString(action.id)) errors.push(`actions[${index}].id is required`);
		else if (ids.has(action.id)) errors.push(`actions[${index}].id must be unique`);
		else ids.add(action.id);
		if (!nonEmptyString(action.kind)) errors.push(`actions[${index}].kind is required`);
		if (!nonEmptyString(action.label)) errors.push(`actions[${index}].label is required`);
		if (action.input !== undefined && (!record(action.input) || !isJsonValue(action.input))) {
			errors.push(`actions[${index}].input must be JSON-safe`);
		}
	}
}

function validatePayload(kind: UiDocumentKind, payload: Record<string, unknown>, errors: string[]): void {
	const requireString = (key: string) => {
		if (!nonEmptyString(payload[key])) errors.push(`payload.${key} is required`);
	};
	const requireArray = (key: string) => {
		if (!Array.isArray(payload[key])) errors.push(`payload.${key} must be an array`);
	};

	switch (kind) {
		case "quiz": requireString("topic"); requireArray("questions"); break;
		case "question": requireArray("fields"); break;
		case "goal": requireString("goalId"); requireString("title"); requireString("status"); requireArray("steps"); break;
		case "deck": requireString("deckId"); requireString("topic"); requireString("title"); requireArray("cards"); break;
		case "image":
			requireString("title"); requireString("alt");
			if (!nonEmptyString(payload.url) && !nonEmptyString(payload.dataUrl)) errors.push("payload.url or payload.dataUrl is required");
			break;
		case "scene":
			if (![payload.body, payload.storyboard, payload.markdown].some(nonEmptyString)) errors.push("scene payload requires body, storyboard, or markdown");
			break;
		case "artifact": requireString("uri"); break;
		case "generic": requireString("format"); break;
	}
}

export function validateUiDocument(value: unknown): ValidationResult<UiDocument> {
	const errors: string[] = [];
	if (!record(value)) return { ok: false, errors: ["document must be an object"] };
	if (value.protocol !== KEATING_UI_PROTOCOL) errors.push(`protocol must be ${KEATING_UI_PROTOCOL}`);
	if (value.version !== KEATING_UI_VERSION) errors.push(`version must be ${KEATING_UI_VERSION}`);
	if (!nonEmptyString(value.id)) errors.push("id is required");
	if (!revision(value.revision)) errors.push("revision must be a non-negative safe integer");
	if (!nonEmptyString(value.kind) || !DOCUMENT_KINDS.has(value.kind as UiDocumentKind)) errors.push("kind is unsupported");
	if (!record(value.payload)) errors.push("payload must be an object");
	else {
		if (!isJsonValue(value.payload)) errors.push("payload must be JSON-safe");
		if (DOCUMENT_KINDS.has(value.kind as UiDocumentKind)) validatePayload(value.kind as UiDocumentKind, value.payload, errors);
	}
	validateActions(value.actions, errors);
	return errors.length === 0 ? { ok: true, value: value as unknown as UiDocument, errors } : { ok: false, errors };
}

export function isUiDocument(value: unknown): value is UiDocument {
	return validateUiDocument(value).ok;
}

export function validateUiActionRequest(value: unknown): ValidationResult<UiActionRequest> {
	const errors: string[] = [];
	if (!record(value)) return { ok: false, errors: ["action request must be an object"] };
	if (value.protocol !== KEATING_UI_PROTOCOL) errors.push(`protocol must be ${KEATING_UI_PROTOCOL}`);
	if (value.version !== KEATING_UI_VERSION) errors.push(`version must be ${KEATING_UI_VERSION}`);
	for (const key of ["id", "documentId", "actionId", "createdAt"] as const) {
		if (!nonEmptyString(value[key])) errors.push(`${key} is required`);
	}
	if (!revision(value.documentRevision)) errors.push("documentRevision must be a non-negative safe integer");
	if (!record(value.payload) || !isJsonValue(value.payload)) errors.push("payload must be a JSON-safe object");
	return errors.length === 0 ? { ok: true, value: value as unknown as UiActionRequest, errors } : { ok: false, errors };
}

export function isUiActionRequest(value: unknown): value is UiActionRequest {
	return validateUiActionRequest(value).ok;
}

export function validateUiActionResult(value: unknown): ValidationResult<UiActionResult> {
	const errors: string[] = [];
	if (!record(value)) return { ok: false, errors: ["action result must be an object"] };
	if (value.protocol !== KEATING_UI_PROTOCOL) errors.push(`protocol must be ${KEATING_UI_PROTOCOL}`);
	if (value.version !== KEATING_UI_VERSION) errors.push(`version must be ${KEATING_UI_VERSION}`);
	for (const key of ["id", "actionRequestId", "documentId", "createdAt"] as const) {
		if (!nonEmptyString(value[key])) errors.push(`${key} is required`);
	}
	if (!revision(value.documentRevision)) errors.push("documentRevision must be a non-negative safe integer");
	if (!["accepted", "rejected", "error"].includes(String(value.status))) errors.push("status is unsupported");
	if (value.resultingRevision !== undefined && !revision(value.resultingRevision)) errors.push("resultingRevision must be a non-negative safe integer");
	if (value.payload !== undefined && (!record(value.payload) || !isJsonValue(value.payload))) errors.push("payload must be a JSON-safe object");
	if (value.status === "error" && (!record(value.error) || !nonEmptyString(value.error.code) || !nonEmptyString(value.error.message))) {
		errors.push("error results require error.code and error.message");
	}
	return errors.length === 0 ? { ok: true, value: value as unknown as UiActionResult, errors } : { ok: false, errors };
}

export function isUiActionResult(value: unknown): value is UiActionResult {
	return validateUiActionResult(value).ok;
}

export function actionTargetsDocument(request: UiActionRequest, document: UiDocument): boolean {
	return request.documentId === document.id && request.documentRevision === document.revision;
}

export function resultCorrelatesToAction(result: UiActionResult, request: UiActionRequest): boolean {
	return result.actionRequestId === request.id
		&& result.documentId === request.documentId
		&& result.documentRevision === request.documentRevision;
}

export * from "./types";
export * from "./validation";
export * from "./legacy";

export const KEATING_UI_PROTOCOL = "keating.ui" as const;
export const KEATING_UI_VERSION = 1 as const;

export type JsonPrimitive = string | number | boolean | null;
export type JsonValue = JsonPrimitive | JsonValue[] | { [key: string]: JsonValue };
export type JsonObject = { [key: string]: JsonValue };

export type UiDocumentKind =
	| "quiz"
	| "question"
	| "goal"
	| "deck"
	| "image"
	| "scene"
	| "artifact"
	| "generic";

export type UiDocumentStatus = "active" | "submitted" | "completed" | "disabled" | "error";

export interface UiActionDefinition {
	id: string;
	kind:
		| "submit"
		| "answer"
		| "select"
		| "update_step"
		| "review_card"
		| "request_reframe"
		| "request_remediation"
		| "open"
		| "retry"
		| "custom";
	label: string;
	description?: string;
	destructive?: boolean;
	disabled?: boolean;
	input?: JsonObject;
}

interface UiDocumentBase<K extends UiDocumentKind, P extends JsonObject> {
	protocol: typeof KEATING_UI_PROTOCOL;
	version: typeof KEATING_UI_VERSION;
	id: string;
	revision: number;
	kind: K;
	createdAt?: string;
	title?: string;
	status?: UiDocumentStatus;
	actions?: UiActionDefinition[];
	payload: P;
}

export interface QuizQuestionDocument extends JsonObject {
	id: string;
	prompt: string;
	type: string;
	level?: string;
	options?: string[];
	blanks?: Array<{ placeholder?: string; hint?: string }>;
	min?: number;
	max?: number;
	step?: number;
	explanation?: string;
	rubric?: string;
}

export interface QuizPayload extends JsonObject {
	topic: string;
	questions: QuizQuestionDocument[];
	totalPoints?: number;
	answers?: JsonObject;
	grades?: JsonObject;
	resultId?: string;
}

export interface QuestionFieldDocument extends JsonObject {
	id: string;
	prompt: string;
	type: "choice" | "text" | "blanks" | "classification" | "matching" | string;
	header?: string;
	choices?: string[];
	items?: string[];
	blanks?: Array<{ placeholder?: string; hint?: string }>;
	hint?: string;
	allowText?: boolean;
	multiSelect?: boolean;
	requireReasons?: boolean;
	uniqueMatches?: boolean;
}

export interface QuestionPayload extends JsonObject {
	intro?: string;
	topic?: string;
	fields: QuestionFieldDocument[];
	answers?: JsonObject;
}

export interface GoalStepDocument extends JsonObject {
	id: string;
	title: string;
	status: "not_started" | "in_progress" | "done" | string;
	order?: number;
	kind?: string;
	description?: string;
	topic?: string;
	successCriteria?: string[];
}

export interface GoalPayload extends JsonObject {
	goalId: string;
	title: string;
	description?: string;
	motivation?: string;
	status: string;
	steps: GoalStepDocument[];
	progress?: number;
}

export interface FlashcardDocument extends JsonObject {
	id: string;
	front: string;
	back: string;
	tags?: string[];
	dueAt?: number;
	state?: JsonObject;
}

export interface DeckPayload extends JsonObject {
	deckId: string;
	topic: string;
	title: string;
	description?: string;
	cards: FlashcardDocument[];
	restrictToCardIds?: string[];
}

export interface ImagePayload extends JsonObject {
	title: string;
	alt: string;
	url?: string;
	dataUrl?: string;
	mimeType?: string;
	model?: string;
	prompt?: string;
}

export interface ScenePayload extends JsonObject {
	topic?: string;
	kind?: string;
	summary?: string;
	storyboard?: string;
	body?: string;
	markdown?: string;
	renderer?: string;
}

export interface ArtifactPayload extends JsonObject {
	artifactId?: string;
	uri: string;
	artifactType?: string;
	label?: string;
	mediaType?: string;
	summary?: string;
	content?: string;
}

export interface GenericPayload extends JsonObject {
	format: "text" | "markdown" | "json" | string;
	content?: string;
	data?: JsonValue;
	originalKind?: string;
}

export type QuizDocument = UiDocumentBase<"quiz", QuizPayload>;
export type QuestionDocument = UiDocumentBase<"question", QuestionPayload>;
export type GoalDocument = UiDocumentBase<"goal", GoalPayload>;
export type DeckDocument = UiDocumentBase<"deck", DeckPayload>;
export type ImageDocument = UiDocumentBase<"image", ImagePayload>;
export type SceneDocument = UiDocumentBase<"scene", ScenePayload>;
export type ArtifactDocument = UiDocumentBase<"artifact", ArtifactPayload>;
export type GenericDocument = UiDocumentBase<"generic", GenericPayload>;

export type UiDocument =
	| QuizDocument
	| QuestionDocument
	| GoalDocument
	| DeckDocument
	| ImageDocument
	| SceneDocument
	| ArtifactDocument
	| GenericDocument;

export interface UiActionRequest {
	protocol: typeof KEATING_UI_PROTOCOL;
	version: typeof KEATING_UI_VERSION;
	id: string;
	documentId: string;
	documentRevision: number;
	actionId: string;
	createdAt: string;
	payload: JsonObject;
}

export interface UiActionResult {
	protocol: typeof KEATING_UI_PROTOCOL;
	version: typeof KEATING_UI_VERSION;
	id: string;
	actionRequestId: string;
	documentId: string;
	documentRevision: number;
	status: "accepted" | "rejected" | "error";
	createdAt: string;
	resultingRevision?: number;
	payload?: JsonObject;
	error?: { code: string; message: string; retryable?: boolean };
}
